export function Button({ children, className = '', ...props }) {
    return (
      <button
        className={`px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 
                   disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors
                   ${className}`}
        {...props}
      >
        {children}
      </button>
    );
  }
